const STORAGE_KEY = "offline-chess-game";

export type SavedGameState = {
  fen: string;
  boardOrientation: "white" | "black";
};

export function loadSavedGame(): SavedGameState | null {
  if (typeof window === "undefined") return null;

  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw) as SavedGameState;
    if (!parsed.fen || !parsed.boardOrientation) return null;

    return parsed;
  } catch {
    return null;
  }
}

export function saveGame(state: SavedGameState): void {
  if (typeof window === "undefined") return;

  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Ignore quota/private-mode errors.
  }
}

export function clearSavedGame(): void {
  if (typeof window === "undefined") return;
  window.localStorage.removeItem(STORAGE_KEY);
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Chess, Color, Move, Square } from "chess.js";
import {
  clearSavedGame,
  loadSavedGame,
  saveGame
} from "@/lib/gameStorage";

export type GameStatus =
  | "ongoing"
  | "check"
  | "checkmate"
  | "draw"
  | "stalemate";

const getStatus = (game: Chess): GameStatus => {
  if (game.isCheckmate()) return "checkmate";
  if (game.isStalemate()) return "stalemate";
  if (game.isDraw()) return "draw";
  if (game.isCheck()) return "check";
  return "ongoing";
};

const formatTurn = (turn: Color) => (turn === "w" ? "White" : "Black");

const createGameFromFen = (fen: string): Chess | null => {
  try {
    return new Chess(fen);
  } catch {
    return null;
  }
};

export function useChessGame() {
  const [game, setGame] = useState(() => new Chess());
  const [boardOrientation, setBoardOrientation] = useState<"white" | "black">(
    "white"
  );
  // Avoid writing default state over saved data before restore finishes.
  const [hasRestored, setHasRestored] = useState(false);

  useEffect(() => {
    const saved = loadSavedGame();
    if (saved) {
      const restored = createGameFromFen(saved.fen);
      if (restored) {
        setGame(restored);
        setBoardOrientation(saved.boardOrientation);
      } else {
        clearSavedGame();
      }
    }
    setHasRestored(true);
  }, []);

  useEffect(() => {
    if (!hasRestored) return;

    saveGame({
      fen: game.fen(),
      boardOrientation
    });
  }, [game, boardOrientation, hasRestored]);

  const makeMove = useCallback((from: Square, to: Square): boolean => {
    let moveMade = false;

    setGame((currentGame) => {
      // Clone state before mutating so React gets a new object reference.
      const nextGame = new Chess(currentGame.fen());
      const move = nextGame.move({ from, to, promotion: "q" });

      if (move) {
        moveMade = true;
      }

      return nextGame;
    });

    return moveMade;
  }, []);

  const newGame = useCallback(() => {
    const freshGame = new Chess();
    setGame(freshGame);
    setBoardOrientation("white");
    saveGame({ fen: freshGame.fen(), boardOrientation: "white" });
  }, []);

  const undoMove = useCallback(() => {
    setGame((currentGame) => {
      const nextGame = new Chess(currentGame.fen());
      nextGame.undo();
      return nextGame;
    });
  }, []);

  const flipBoard = useCallback(() => {
    setBoardOrientation((prev) => (prev === "white" ? "black" : "white"));
  }, []);

  const moveHistory = useMemo<Move[]>(() => game.history({ verbose: true }), [game]);
  const gameStatus = useMemo(() => getStatus(game), [game]);

  return {
    fen: game.fen(),
    turn: formatTurn(game.turn()),
    gameStatus,
    boardOrientation,
    moveHistory,
    canUndo: moveHistory.length > 0,
    makeMove,
    newGame,
    undoMove,
    flipBoard
  };
}

import { Chess, Move } from "chess.js";

const SOUND_PREF_KEY = "offline-chess-sound-enabled";

let audioContext: AudioContext | null = null;

const getAudioContext = (): AudioContext => {
  if (!audioContext) {
    audioContext = new AudioContext();
  }
  return audioContext;
};

export function loadSoundEnabled(): boolean {
  if (typeof window === "undefined") return true;

  try {
    const value = window.localStorage.getItem(SOUND_PREF_KEY);
    if (value === null) return true;
    return value === "true";
  } catch {
    return true;
  }
}

export function saveSoundEnabled(enabled: boolean): void {
  if (typeof window === "undefined") return;

  try {
    window.localStorage.setItem(SOUND_PREF_KEY, String(enabled));
  } catch {
    // Ignore storage errors.
  }
}

let soundEnabled = true;

export function setSoundEnabled(enabled: boolean): void {
  soundEnabled = enabled;
  saveSoundEnabled(enabled);
}

export function isSoundEnabled(): boolean {
  return soundEnabled;
}

export function initSoundPreference(): void {
  soundEnabled = loadSoundEnabled();
}

async function resumeAudioContext(): Promise<void> {
  const ctx = getAudioContext();
  if (ctx.state === "suspended") {
    await ctx.resume();
  }
}

function playTone(
  frequency: number,
  durationMs: number,
  volume = 0.08,
  type: OscillatorType = "sine"
): void {
  if (!soundEnabled) return;

  const ctx = getAudioContext();
  const oscillator = ctx.createOscillator();
  const gain = ctx.createGain();

  oscillator.type = type;
  oscillator.frequency.value = frequency;
  gain.gain.value = volume;

  oscillator.connect(gain);
  gain.connect(ctx.destination);

  const now = ctx.currentTime;
  oscillator.start(now);
  gain.gain.exponentialRampToValueAtTime(0.001, now + durationMs / 1000);
  oscillator.stop(now + durationMs / 1000);
}

function playSequence(
  notes: Array<{ frequency: number; durationMs: number; volume?: number }>
): void {
  if (!soundEnabled) return;

  let delay = 0;
  for (const note of notes) {
    window.setTimeout(() => {
      playTone(note.frequency, note.durationMs, note.volume ?? 0.08);
    }, delay);
    delay += note.durationMs * 0.7;
  }
}

export async function playMoveSound(game: Chess, move: Move): Promise<void> {
  if (!soundEnabled) return;
  await resumeAudioContext();

  if (game.isCheckmate()) {
    playSequence([
      { frequency: 523, durationMs: 120 },
      { frequency: 659, durationMs: 120 },
      { frequency: 784, durationMs: 180, volume: 0.1 }
    ]);
    return;
  }

  if (game.isStalemate() || game.isDraw()) {
    playTone(392, 180, 0.07);
    return;
  }

  if (move.flags.includes("k") || move.flags.includes("q")) {
    playSequence([
      { frequency: 330, durationMs: 90 },
      { frequency: 440, durationMs: 110 }
    ]);
