  }

  if (move.captured) {
    playSequence([
      { frequency: 220, durationMs: 70, volume: 0.09 },
      { frequency: 180, durationMs: 90, volume: 0.08 }
    ]);
    return;
  }

  if (game.isCheck()) {
    playTone(740, 120, 0.09, "triangle");
    return;
  }

  playTone(440, 70, 0.06);
}

